/* ---------- Signature element: speedometer arc ---------- */
function Arc({ pct = 70, size = 120, stroke = 6, color = C.blueBright, track = "rgba(255,255,255,0.12)", label, value }) {
  const r = (size - stroke) / 2;
  const circumference = Math.PI * 1.5 * r; // 270 degree sweep
  const offset = circumference * (1 - pct / 100);
  return (
    <div style={{ position: "relative", width: size, height: size }}>
      <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} style={{ transform: "rotate(135deg)" }}>
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={track} strokeWidth={stroke}
          strokeDasharray={`${circumference} ${circumference}`} strokeDashoffset={circumference * 0.25} strokeLinecap="round" />
        <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={stroke}
          strokeDasharray={`${circumference} ${circumference}`} strokeDashoffset={offset + circumference * 0.25}
          strokeLinecap="round" style={{ transition: "stroke-dashoffset 1.2s cubic-bezier(.4,0,.2,1)" }} />
      </svg>
      <div style={{ position: "absolute", inset: 0, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontFamily: "'Barlow Condensed', sans-serif", fontSize: size * 0.24, fontWeight: 700, color: C.white, lineHeight: 1 }}>{value}</span>
        <span style={{ fontFamily: "'Inter', sans-serif", fontSize: size * 0.075, color: "rgba(255,255,255,0.55)", letterSpacing: 1, textTransform: "uppercase", marginTop: 4 }}>{label}</span>
      </div>
    </div>
  );
}

function ArcDivider({ dark = false }) {
  return (
    <div style={{ display: "flex", alignItems: "center", justifyContent: "center", padding: "8px 0" }}>
      <svg width="140" height="28" viewBox="0 0 140 28">
        <path d="M4 24 A 66 66 0 0 1 136 24" fill="none" stroke={dark ? "rgba(255,255,255,0.25)" : C.chrome} strokeWidth="2" strokeLinecap="round" />
        {[0, 0.25, 0.5, 0.75, 1].map((t, i) => {
          const angle = Math.PI * (1 - t);
          const x = 70 + 66 * Math.cos(angle);
          const y = 24 - 66 * Math.sin(angle);
          return <circle key={i} cx={x} cy={y} r={i === 2 ? 3 : 2} fill={i === 2 ? C.blueBright : (dark ? "rgba(255,255,255,0.4)" : C.steel)} />;
        })}
      </svg>
    </div>
  );
}

/* ---------- Logomark (real brand logo) ---------- */
