/* ---------- Gallery (for vehicles with real photos) ---------- */
function VehicleGallery({ photos }) {
  const [idx, setIdx] = useState(0);
  const prev = (e) => { e.stopPropagation(); setIdx((i) => (i - 1 + photos.length) % photos.length); };
  const next = (e) => { e.stopPropagation(); setIdx((i) => (i + 1) % photos.length); };
  return (
    <div style={{ position: "relative", height: 300, background: C.black, overflow: "hidden" }}>
      <img src={photos[idx]} alt="" style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: "center 68%", display: "block" }} />
      <div style={{ position: "absolute", top: 12, left: 12, fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.white, background: "rgba(13,13,13,0.55)", padding: "3px 8px", borderRadius: 2, letterSpacing: 1 }}>
        {idx + 1} / {photos.length}
      </div>
      <button onClick={prev} aria-label="Foto anterior" style={{
        position: "absolute", left: 8, top: "50%", transform: "translateY(-50%)", width: 30, height: 30,
        borderRadius: "50%", border: "none", background: "rgba(13,13,13,0.55)", color: C.white,
        cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center"
      }}>‹</button>
      <button onClick={next} aria-label="Foto siguiente" style={{
        position: "absolute", right: 8, top: "50%", transform: "translateY(-50%)", width: 30, height: 30,
        borderRadius: "50%", border: "none", background: "rgba(13,13,13,0.55)", color: C.white,
        cursor: "pointer", display: "flex", alignItems: "center", justifyContent: "center"
      }}>›</button>
      <div style={{ position: "absolute", bottom: 8, left: 0, right: 0, display: "flex", justifyContent: "center", gap: 4 }}>
        {photos.map((_, i) => (
          <span key={i} onClick={(e) => { e.stopPropagation(); setIdx(i); }} style={{
            width: 5, height: 5, borderRadius: "50%", cursor: "pointer",
            background: i === idx ? C.blueBright : "rgba(255,255,255,0.4)"
          }} />
        ))}
      </div>
    </div>
  );
}

const numFrom = (s) => parseInt(String(s).replace(/[^0-9]/g, ""), 10) || 0;
const formatCLP = (n) => "$" + Math.round(n).toLocaleString("es-CL");

/* ---------- Page: Catálogo ---------- */
function Catalogo({ openVehicle }) {
  const [marca, setMarca] = useState("Todas");
  const [año, setAño] = useState("Todos");
  const [orden, setOrden] = useState("recientes");

  const marcas = ["Todas", ...Array.from(new Set(CATALOGO.map((v) => v.marca)))];
  const años = ["Todos", ...Array.from(new Set(CATALOGO.map((v) => v.año))).sort((a, b) => b - a)];

  let items = CATALOGO.filter((v) => (marca === "Todas" || v.marca === marca) && (año === "Todos" || v.año === año));
  if (orden === "km_asc") items = [...items].sort((a, b) => numFrom(a.km) - numFrom(b.km));
  if (orden === "km_desc") items = [...items].sort((a, b) => numFrom(b.km) - numFrom(a.km));
  if (orden === "precio_asc") items = [...items].sort((a, b) => numFrom(a.precio) - numFrom(b.precio));
  if (orden === "precio_desc") items = [...items].sort((a, b) => numFrom(b.precio) - numFrom(a.precio));

  const selectStyle = {
    fontFamily: "'Inter', sans-serif", fontSize: 13.5, color: C.black, background: C.white,
    border: `1.5px solid ${C.chrome}`, borderRadius: 3, padding: "9px 12px", cursor: "pointer", outline: "none",
  };

  return (
    <section style={{ background: C.paper, padding: "140px 24px 100px" }}>
      <div style={{ maxWidth: 1080, margin: "0 auto" }}>
        <Reveal>
          <Eyebrow>Inventario</Eyebrow>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-end", flexWrap: "wrap", gap: 16, marginBottom: 28 }}>
            <h1 style={{ fontFamily: "'Barlow Condensed', sans-serif", fontSize: "clamp(38px,5vw,58px)", textTransform: "uppercase", color: C.black, margin: 0 }}>
              Catálogo
            </h1>
            <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, color: C.steel, background: C.white, border: `1px solid ${C.chrome}`, padding: "6px 12px", borderRadius: 3 }}>
              {items.length} VEHÍCULOS
            </span>
          </div>
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 40 }}>
            <select value={marca} onChange={(e) => setMarca(e.target.value)} style={selectStyle}>
              {marcas.map((m) => <option key={m} value={m}>{m === "Todas" ? "Marca: todas" : m}</option>)}
            </select>
            <select value={año} onChange={(e) => setAño(e.target.value)} style={selectStyle}>
              {años.map((a) => <option key={a} value={a}>{a === "Todos" ? "Año: todos" : a}</option>)}
            </select>
            <select value={orden} onChange={(e) => setOrden(e.target.value)} style={selectStyle}>
              <option value="recientes">Orden: más recientes</option>
              <option value="km_asc">Menor kilometraje</option>
              <option value="km_desc">Mayor kilometraje</option>
              <option value="precio_asc">Menor precio</option>
              <option value="precio_desc">Mayor precio</option>
            </select>
            {(marca !== "Todas" || año !== "Todos" || orden !== "recientes") && (
              <button onClick={() => { setMarca("Todas"); setAño("Todos"); setOrden("recientes"); }} style={{
                ...selectStyle, background: "transparent", border: "1.5px solid transparent", color: C.blue, fontWeight: 600
              }}>Limpiar filtros</button>
            )}
          </div>
        </Reveal>
        {items.length === 0 && (
          <p style={{ fontFamily: "'Inter', sans-serif", color: C.steel, fontSize: 15 }}>No hay vehículos que coincidan con estos filtros.</p>
        )}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", gap: 22 }}>
          {items.map((v, i) => {
            const vendido = v.estado === "Vendido";
            return (
            <Reveal key={i} delay={i * 0.06}>
              <div style={{ background: C.white, border: `1px solid ${C.chrome}`, borderRadius: 4, overflow: "hidden", opacity: vendido ? 0.6 : 1, cursor: "pointer" }} onClick={() => openVehicle(v)}>
                {v.fotos ? (
                  <div style={{ position: "relative" }}>
                    <VehicleGallery photos={v.fotos} />
                    {v.estado && (
                      <span style={{ position: "absolute", top: 12, right: 12, zIndex: 2, fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, letterSpacing: 1, textTransform: "uppercase", padding: "4px 10px", borderRadius: 2, background: ESTADO_STYLE[v.estado]?.bg, color: ESTADO_STYLE[v.estado]?.fg }}>
                        {v.estado}
                      </span>
                    )}
                  </div>
                ) : (
                  <div style={{ background: C.black, height: 130, display: "flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
                    <Car size={40} color="rgba(255,255,255,0.25)" strokeWidth={1} />
                    <span style={{ position: "absolute", top: 12, left: 12, fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: "rgba(255,255,255,0.5)", letterSpacing: 1.5, textTransform: "uppercase" }}>Foto próximamente</span>
                    {v.estado && (
                      <span style={{ position: "absolute", top: 12, right: 12, fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, letterSpacing: 1, textTransform: "uppercase", padding: "4px 10px", borderRadius: 2, background: ESTADO_STYLE[v.estado]?.bg, color: ESTADO_STYLE[v.estado]?.fg }}>
                        {v.estado}
                      </span>
                    )}
                  </div>
                )}
                <div style={{ padding: 22 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                    <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11.5, color: C.steel, letterSpacing: 1, textTransform: "uppercase" }}>{v.marca}</div>
                  </div>
                  <h3 style={{ fontFamily: "'Barlow Condensed', sans-serif", fontSize: 24, color: C.black, margin: "4px 0 14px", textTransform: "uppercase" }}>{v.modelo}</h3>
                  <div style={{ display: "flex", gap: 16, flexWrap: "wrap", marginBottom: 16 }}>
                    <span style={{ display: "flex", alignItems: "center", gap: 5, fontFamily: "'Inter',sans-serif", fontSize: 12.5, color: C.steel }}><Calendar size={13} />{v.año}</span>
                    <span style={{ display: "flex", alignItems: "center", gap: 5, fontFamily: "'Inter',sans-serif", fontSize: 12.5, color: C.steel }}><Gauge size={13} />{v.km} km</span>
                    <span style={{ display: "flex", alignItems: "center", gap: 5, fontFamily: "'Inter',sans-serif", fontSize: 12.5, color: C.steel }}><Fuel size={13} />{v.comb}</span>
                    <span style={{ display: "flex", alignItems: "center", gap: 5, fontFamily: "'Inter',sans-serif", fontSize: 12.5, color: C.steel }}><Settings2 size={13} />{v.trans}</span>
                  </div>
                  <div style={{ borderTop: `1px solid ${C.chrome}`, paddingTop: 14, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <span style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 19, fontWeight: 700, color: C.blue }}>{v.precio}</span>
                    <ArrowUpRight size={18} color={C.steel} />
                  </div>
                </div>
              </div>
            </Reveal>
          );})}
        </div>
      </div>
    </section>
  );
}

/* ---------- Page: Vehicle Detail ---------- */
function VehicleDetail({ v, go }) {
  const [idx, setIdx] = useState(0);
  if (!v) {
    return (
      <section style={{ background: C.paper, padding: "160px 24px 100px", textAlign: "center" }}>
        <p style={{ fontFamily: "'Inter', sans-serif", color: C.steel }}>No se encontró el vehículo.</p>
        <div style={{ marginTop: 20 }}>
          <Button variant="dark" onClick={() => go("catalogo")}>Volver al catálogo</Button>
        </div>
      </section>
    );
  }
  const photos = v.fotos;
  const vendido = v.estado === "Vendido";
  const desc = v.descripcion || `${v.marca} ${v.modelo}, año ${v.año}, con ${v.km} km. Transmisión ${v.trans?.toLowerCase()}, motor a ${v.comb?.toLowerCase()}. Vehículo revisado y con documentación al día, disponible para evaluación presencial o virtual.`;

  return (
    <section style={{ background: C.paper, padding: "120px 24px 100px" }}>
      <div style={{ maxWidth: 1080, margin: "0 auto" }}>
        <button onClick={() => go("catalogo")} style={{
          background: "none", border: "none", cursor: "pointer", display: "flex", alignItems: "center", gap: 6,
          fontFamily: "'Inter', sans-serif", fontSize: 13.5, color: C.steel, fontWeight: 600, marginBottom: 24, padding: 0
        }}>
          <ChevronRight size={14} style={{ transform: "rotate(180deg)" }} /> Volver al catálogo
        </button>

        <div className="two-col-grid" style={{ gap: 44 }}>
          <Reveal>
            {photos ? (
              <div style={{ maxWidth: 480, margin: "0 auto", width: "100%" }}>
                <div style={{ position: "relative", width: "100%", background: C.black, overflow: "hidden", borderRadius: 4 }}>
                  <img src={photos[idx]} alt="" style={{ width: "100%", height: "auto", display: "block" }} />
                  {v.estado && (
                    <span style={{ position: "absolute", top: 14, right: 14, fontFamily: "'JetBrains Mono', monospace", fontSize: 11, letterSpacing: 1, textTransform: "uppercase", padding: "5px 12px", borderRadius: 2, background: ESTADO_STYLE[v.estado]?.bg, color: ESTADO_STYLE[v.estado]?.fg }}>
                      {v.estado}
                    </span>
                  )}
                  <button onClick={() => setIdx((i) => (i - 1 + photos.length) % photos.length)} aria-label="Anterior" style={{
                    position: "absolute", left: 10, top: "50%", transform: "translateY(-50%)", width: 36, height: 36,
                    borderRadius: "50%", border: "none", background: "rgba(13,13,13,0.55)", color: C.white, cursor: "pointer"
                  }}>‹</button>
                  <button onClick={() => setIdx((i) => (i + 1) % photos.length)} aria-label="Siguiente" style={{
                    position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", width: 36, height: 36,
                    borderRadius: "50%", border: "none", background: "rgba(13,13,13,0.55)", color: C.white, cursor: "pointer"
                  }}>›</button>
                  <div style={{ position: "absolute", bottom: 12, left: 12, fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.white, background: "rgba(13,13,13,0.55)", padding: "3px 9px", borderRadius: 2 }}>
                    {idx + 1} / {photos.length}
                  </div>
                </div>
                <div style={{ display: "flex", gap: 8, marginTop: 10, overflowX: "auto", paddingBottom: 4, justifyContent: "center" }}>
                  {photos.map((p, i) => (
                    <img key={i} src={p} onClick={() => setIdx(i)} alt="" style={{
                      width: 64, height: 48, objectFit: "cover", objectPosition: "center 68%", borderRadius: 3, cursor: "pointer",
                      flexShrink: 0, opacity: i === idx ? 1 : 0.5, border: i === idx ? `2px solid ${C.blueBright}` : "2px solid transparent"
                    }} />
                  ))}
                </div>
              </div>
            ) : (
              <div style={{ background: C.black, aspectRatio: "4 / 5", width: "100%", maxWidth: 440, margin: "0 auto", borderRadius: 4, display: "flex", alignItems: "center", justifyContent: "center", position: "relative" }}>
                <Car size={56} color="rgba(255,255,255,0.25)" strokeWidth={1} />
                <span style={{ position: "absolute", top: 14, left: 14, fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: "rgba(255,255,255,0.5)", letterSpacing: 1.5, textTransform: "uppercase" }}>Foto próximamente</span>
                {v.estado && (
                  <span style={{ position: "absolute", top: 14, right: 14, fontFamily: "'JetBrains Mono', monospace", fontSize: 11, letterSpacing: 1, textTransform: "uppercase", padding: "5px 12px", borderRadius: 2, background: ESTADO_STYLE[v.estado]?.bg, color: ESTADO_STYLE[v.estado]?.fg }}>
                    {v.estado}
                  </span>
                )}
              </div>
            )}
          </Reveal>

          <Reveal delay={0.08}>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 12, color: C.steel, letterSpacing: 1, textTransform: "uppercase" }}>{v.marca}</div>
            <h1 style={{ fontFamily: "'Barlow Condensed', sans-serif", fontSize: "clamp(30px,4vw,42px)", textTransform: "uppercase", color: C.black, margin: "4px 0 14px", lineHeight: 1 }}>
              {v.modelo}
            </h1>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 28, fontWeight: 700, color: C.blue, marginBottom: 22 }}>
              {v.precio}
            </div>

            <div className="spec-grid" style={{ background: C.white, border: `1px solid ${C.chrome}`, borderRadius: 4, padding: 20, marginBottom: 22 }}>
              <div>
                <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>Año</div>
                <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 15, color: C.black, marginTop: 2, display: "flex", alignItems: "center", gap: 6 }}><Calendar size={14} />{v.año}</div>
              </div>
              <div>
                <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>Kilometraje</div>
                <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 15, color: C.black, marginTop: 2, display: "flex", alignItems: "center", gap: 6 }}><Gauge size={14} />{v.km} km</div>
              </div>
              <div>
                <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>Combustible</div>
                <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 15, color: C.black, marginTop: 2, display: "flex", alignItems: "center", gap: 6 }}><Fuel size={14} />{v.comb}</div>
              </div>
              <div>
                <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>Transmisión</div>
                <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 15, color: C.black, marginTop: 2, display: "flex", alignItems: "center", gap: 6 }}><Settings2 size={14} />{v.trans}</div>
              </div>
              {v.motor && (
                <div style={{ gridColumn: "1 / -1" }}>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>Motor</div>
                  <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 14.5, color: C.black, marginTop: 2 }}>{v.motor}</div>
                </div>
              )}
              {v.potencia && (
                <div>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>Potencia</div>
                  <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 15, color: C.black, marginTop: 2 }}>{v.potencia}</div>
                </div>
              )}
              {v.dueños && (
                <div>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>Dueños</div>
                  <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 15, color: C.black, marginTop: 2 }}>{v.dueños}</div>
                </div>
              )}
            </div>

            <p style={{ fontFamily: "'Inter', sans-serif", color: C.steel, fontSize: 14.5, lineHeight: 1.7, marginBottom: v.equipamiento ? 18 : 26, whiteSpace: "pre-line" }}>
              {desc}
            </p>

            {v.equipamiento && (
              <div style={{ marginBottom: 20 }}>
                <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.steel, textTransform: "uppercase", letterSpacing: 1, marginBottom: 10 }}>Equipamiento destacado</div>
                <ul style={{ margin: 0, paddingLeft: 18, display: "flex", flexDirection: "column", gap: 6 }}>
                  {v.equipamiento.map((eq, i) => (
                    <li key={i} style={{ fontFamily: "'Inter', sans-serif", fontSize: 14, color: C.black, lineHeight: 1.5 }}>{eq}</li>
                  ))}
                </ul>
              </div>
            )}

            {v.financiamientoPie && (
              <div style={{ background: "#EAF0FB", border: `1px solid ${C.blue}22`, borderRadius: 4, padding: "12px 16px", marginBottom: 26, display: "flex", alignItems: "center", gap: 10 }}>
                <ShieldCheck size={16} color={C.blue} />
                <span style={{ fontFamily: "'Inter', sans-serif", fontSize: 13.5, color: C.blue, fontWeight: 600 }}>
                  Financiamiento desde {Math.round(v.financiamientoPie * 100)}% pie ({formatCLP(numFrom(v.precio) * v.financiamientoPie)})
                </span>
              </div>
            )}

            <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
              <Button variant="dark" onClick={() => go("contacto")}>
                {vendido ? "Consultar por similares" : "Consultar por este vehículo"}
              </Button>
              <Button variant="outlineDark" onClick={() => go("catalogo")} icon={false}>Ver más vehículos</Button>
            </div>
          </Reveal>
        </div>
      </div>
    </section>
  );
}

/* ---------- Page: Contacto ---------- */
const WHATSAPP_NUM = "56983097794";
const DIRECCION = "Av. Raúl Labbe 12650, Of. 302, Lo Barnechea, Santiago";
const MAPS_DIRECTIONS_URL = `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(DIRECCION)}`;
const WAZE_URL = `https://waze.com/ul?q=${encodeURIComponent(DIRECCION)}&navigate=yes`;

function Contacto() {
  const [form, setForm] = useState({ nombre: "", correo: "", telefono: "", mensaje: "" });
  const [enviado, setEnviado] = useState(false);
  const update = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const enviarWhatsApp = (e) => {
    e.preventDefault();
    const texto =
      `Hola, soy ${form.nombre}.%0A` +
      `Correo: ${form.correo}%0A` +
      `Teléfono: ${form.telefono}%0A%0A` +
      `${form.mensaje}`;
    window.open(`https://wa.me/${WHATSAPP_NUM}?text=${texto}`, "_blank");
    setEnviado(true);
  };

  return (
    <section style={{ background: C.paper, padding: "140px 24px 100px" }}>
      <div className="two-col-grid" style={{ maxWidth: 1080, margin: "0 auto", gap: 60 }}>
        <Reveal>
          <Eyebrow>Hablemos</Eyebrow>
          <h1 style={{ fontFamily: "'Barlow Condensed', sans-serif", fontSize: "clamp(34px,4.5vw,52px)", textTransform: "uppercase", color: C.black, margin: "0 0 24px" }}>
            Contacto
          </h1>
          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>
            {[
              { icon: MapPin, t: "Dirección", v: DIRECCION, href: MAPS_DIRECTIONS_URL },
              { icon: Phone, t: "Teléfono", v: "+56 9 8309 7794", href: `tel:+${WHATSAPP_NUM}` },
              { icon: Mail, t: "Email", v: "rossmannautos@gmail.com", href: "mailto:rossmannautos@gmail.com" },
            ].map((it, i) => (
              <div key={i} style={{ display: "flex", gap: 16, alignItems: "flex-start" }}>
                <div style={{ background: C.black, width: 42, height: 42, borderRadius: 3, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
                  <it.icon size={18} color={C.blueBright} />
                </div>
                <div>
                  <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.steel, textTransform: "uppercase", letterSpacing: 1 }}>{it.t}</div>
                  {it.href ? (
                    <a href={it.href} target={it.href.startsWith("http") ? "_blank" : undefined} rel="noopener noreferrer" style={{ fontFamily: "'Inter', sans-serif", fontSize: 15.5, color: C.black, marginTop: 2, display: "block", textDecoration: "none" }}>{it.v}</a>
                  ) : (
                    <div style={{ fontFamily: "'Inter', sans-serif", fontSize: 15.5, color: C.black, marginTop: 2 }}>{it.v}</div>
                  )}
                </div>
              </div>
            ))}
          </div>
          <div style={{ marginTop: 24, display: "flex", gap: 12, flexWrap: "wrap" }}>
            <Button variant="dark" onClick={() => window.open(`https://wa.me/${WHATSAPP_NUM}`, "_blank")}>Escribir por WhatsApp</Button>
            <Button variant="outlineDark" icon={false} onClick={() => window.open(WAZE_URL, "_blank")}>Abrir en Waze</Button>
          </div>

          <ArcDivider />
        </Reveal>

        <Reveal delay={0.1}>
          <div style={{ background: C.white, border: `1px solid ${C.chrome}`, borderRadius: 4, padding: 32 }}>
            {enviado ? (
              <div style={{ textAlign: "center", padding: "30px 0" }}>
                <ShieldCheck size={36} color={C.blueBright} style={{ margin: "0 auto 14px" }} />
                <h3 style={{ fontFamily: "'Barlow Condensed', sans-serif", fontSize: 22, textTransform: "uppercase", color: C.black, margin: "0 0 6px" }}>Te llevamos a WhatsApp</h3>
                <p style={{ fontFamily: "'Inter', sans-serif", color: C.steel, fontSize: 14 }}>Si no se abrió automáticamente, escríbenos al +56 9 8309 7794.</p>
              </div>
            ) : (
              <>
                <h3 style={{ fontFamily: "'Barlow Condensed', sans-serif", fontSize: 24, textTransform: "uppercase", color: C.black, margin: "0 0 6px" }}>Escríbenos</h3>
                <p style={{ fontFamily: "'Inter', sans-serif", color: C.steel, fontSize: 13, margin: "0 0 20px" }}>Se abrirá WhatsApp con tu mensaje ya listo para enviar.</p>
                <form onSubmit={enviarWhatsApp} style={{ display: "flex", flexDirection: "column", gap: 14 }}>
                  <input required placeholder="Nombre" value={form.nombre} onChange={update("nombre")} style={{
                    fontFamily: "'Inter', sans-serif", padding: "12px 14px", border: `1.5px solid ${C.chrome}`,
                    borderRadius: 3, fontSize: 14.5, outline: "none"
                  }} />
                  <input required type="email" placeholder="Correo" value={form.correo} onChange={update("correo")} style={{
                    fontFamily: "'Inter', sans-serif", padding: "12px 14px", border: `1.5px solid ${C.chrome}`,
                    borderRadius: 3, fontSize: 14.5, outline: "none"
                  }} />
                  <input required placeholder="Teléfono" value={form.telefono} onChange={update("telefono")} style={{
                    fontFamily: "'Inter', sans-serif", padding: "12px 14px", border: `1.5px solid ${C.chrome}`,
                    borderRadius: 3, fontSize: 14.5, outline: "none"
                  }} />
                  <textarea required placeholder="Cuéntanos qué necesitas" rows={4} value={form.mensaje} onChange={update("mensaje")} style={{
                    fontFamily: "'Inter', sans-serif", padding: "12px 14px", border: `1.5px solid ${C.chrome}`,
                    borderRadius: 3, fontSize: 14.5, outline: "none", resize: "vertical"
                  }} />
                  <Button variant="dark" icon={false} style={{ justifyContent: "center", marginTop: 4 }}>
                    <span style={{ width: "100%", textAlign: "center" }}>Enviar por WhatsApp</span>
                  </Button>
                </form>
              </>
            )}
          </div>
        </Reveal>
      </div>
    </section>
  );
}

/* ---------- Nav + Footer ---------- */
const PAGES = [
  { id: "inicio", label: "Inicio" },
  { id: "servicios", label: "Servicios" },
  { id: "catalogo", label: "Catálogo" },
  { id: "contacto", label: "Contacto" },
];

function Nav({ page, go }) {
  const [open, setOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return (
    <header style={{
      position: "fixed", top: 0, left: 0, right: 0, zIndex: 50,
      background: scrolled || page !== "inicio" ? C.black : "rgba(13,13,13,0.0)",
      borderBottom: scrolled || page !== "inicio" ? "1px solid rgba(255,255,255,0.08)" : "1px solid transparent",
      backdropFilter: "blur(6px)", transition: "all .3s ease"
    }}>
      <div style={{ maxWidth: 1120, margin: "0 auto", padding: "14px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <div style={{ display: "flex", alignItems: "center", cursor: "pointer" }} onClick={() => go("inicio")}>
          <Logomark size={46} />
        </div>
        <nav style={{ display: "flex", gap: 4 }} className="desktop-nav">
          {PAGES.map((p) => (
            <button key={p.id} onClick={() => go(p.id)} style={{
              background: "none", border: "none", cursor: "pointer",
              fontFamily: "'Inter', sans-serif", fontSize: 14, fontWeight: 500,
              color: page === p.id ? C.blueBright : "rgba(255,255,255,0.7)",
              padding: "8px 14px", position: "relative"
            }}>
              {p.label}
              {page === p.id && <span style={{ position: "absolute", bottom: 0, left: 14, right: 14, height: 2, background: C.blueBright }} />}
            </button>
          ))}
        </nav>
        <button onClick={() => setOpen(!open)} className="mobile-toggle" style={{ display: "none", background: "none", border: "none", color: C.white }}>
          {open ? <X size={22} /> : <Menu size={22} />}
        </button>
      </div>
      {open && (
        <div style={{ background: C.black, padding: "8px 24px 20px", display: "flex", flexDirection: "column" }} className="mobile-menu">
          {PAGES.map((p) => (
            <button key={p.id} onClick={() => { go(p.id); setOpen(false); }} style={{
              background: "none", border: "none", textAlign: "left", padding: "12px 0",
              fontFamily: "'Inter', sans-serif", fontSize: 15, color: page === p.id ? C.blueBright : "rgba(255,255,255,0.8)"
            }}>{p.label}</button>
          ))}
        </div>
      )}
      <style>{`
        @media (max-width: 780px) {
          .desktop-nav { display: none !important; }
          .mobile-toggle { display: block !important; }
        }
      `}</style>
    </header>
  );
}

function Footer({ go }) {
  return (
    <footer style={{ background: C.black, padding: "50px 24px 30px", borderTop: "1px solid rgba(255,255,255,0.08)" }}>
      <div style={{ maxWidth: 1120, margin: "0 auto", display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 30 }}>
        <div>
          <div style={{ marginBottom: 14 }}>
            <Logomark size={40} />
          </div>
          <p style={{ fontFamily: "'Inter', sans-serif", color: "rgba(255,255,255,0.45)", fontSize: 13, maxWidth: 280, lineHeight: 1.7 }}>
            Av. Raúl Labbe 12650, Of. 302, Lo Barnechea, Santiago.<br />
            <a href="tel:+56983097794" style={{ color: "rgba(255,255,255,0.45)", textDecoration: "none" }}>+56 9 8309 7794</a><br />
            <a href="mailto:rossmannautos@gmail.com" style={{ color: "rgba(255,255,255,0.45)", textDecoration: "none" }}>rossmannautos@gmail.com</a>
          </p>
        </div>
        <div style={{ display: "flex", gap: 40, flexWrap: "wrap" }}>
          <div>
            <div style={{ fontFamily: "'JetBrains Mono', monospace", fontSize: 11, color: C.blueBright, textTransform: "uppercase", marginBottom: 12, letterSpacing: 1 }}>Navegación</div>
            {PAGES.map((p) => (
              <div key={p.id} onClick={() => go(p.id)} style={{ fontFamily: "'Inter', sans-serif", fontSize: 13.5, color: "rgba(255,255,255,0.6)", marginBottom: 8, cursor: "pointer" }}>{p.label}</div>
            ))}
          </div>
        </div>
      </div>
      <div style={{ maxWidth: 1120, margin: "36px auto 0", borderTop: "1px solid rgba(255,255,255,0.08)", paddingTop: 20, fontFamily: "'Inter', sans-serif", fontSize: 12, color: "rgba(255,255,255,0.35)" }}>
        © {new Date().getFullYear()} Comercializadora e Importadora Rossmann SpA. Sitio de demostración.
      </div>
    </footer>
  );
}

/* ---------- App ---------- */
export default function App() {
  const [page, setPage] = useState("inicio");
  const [selectedVehicle, setSelectedVehicle] = useState(null);
  const go = (p) => { setPage(p); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const openVehicle = (v) => { setSelectedVehicle(v); setPage("detalle"); window.scrollTo({ top: 0, behavior: "smooth" }); };

  const render = {
    inicio: <Inicio go={go} openVehicle={openVehicle} />,
    servicios: <Servicios go={go} />,
    catalogo: <Catalogo openVehicle={openVehicle} />,
    detalle: <VehicleDetail v={selectedVehicle} go={go} />,
    contacto: <Contacto />,
  };

  return (
    <div style={{ background: C.paper, minHeight: "100vh", overflowX: "hidden" }}>
      <link rel="preconnect" href="https://fonts.googleapis.com" />
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=Inter:wght@400;500;600&family=JetBrains+Mono:wght@400;500;600&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        html, body { overflow-x: hidden; max-width: 100%; }
        body { -webkit-font-smoothing: antialiased; }
        img { max-width: 100%; }
        button:focus-visible, input:focus-visible, textarea:focus-visible { outline: 2px solid ${C.blueBright}; outline-offset: 2px; }

        .two-col-grid { display: grid; grid-template-columns: 1fr 1fr; }
        .two-col-grid > * { min-width: 0; }
        .spec-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }

        @media (max-width: 760px) {
          .two-col-grid { grid-template-columns: 1fr !important; gap: 32px !important; }
        }
        @media (max-width: 480px) {
          .spec-grid { grid-template-columns: 1fr !important; }
        }
      `}</style>
      <Nav page={page} go={go} />
      {render[page]}
      <Footer go={go} />
    </div>
  );
}
